        language.add("death.attack.boulder", "%1$s is crushed by boulder", "%1$s 被巨石均匀地涂抹在地上");
        language.add("death.attack.darkness", "%1$s was killed by something in the dark!", "%1$s 被黑暗中的什么东西杀死了！");
        language.add("death.attack.darkness.player", "%1$s tried to flee from %2$s, yet never anticipated the scheming of the puppet master", "%1$s 远离 %2$s 时没想到还有幕后黑手");
        language.add("death.attack.dungeon_altar", "Steve was one step away from uncovering the secret by right-clicking tuff with the meteor compass.", "Steve差一步就用陨石指南针右击凝灰岩揭开秘密");
        language.add("death.attack.falling_star", "%1$s got a response from a meteor", "%1$s 得到了流星的回应");
        language.add("death.attack.falling_star.player", "%1$s's wish was finally granted in the presence of %2$s", "%1$s 在 %2$s 的见证下成功实现了愿望");
        language.add("death.attack.frost_burn_damage_type", "%1$s felt warm before the end", "%1$s 至少死前觉得很温暖");
        language.add("death.attack.pass_armor_damage_type", "%1$s was pierced through along with their armor", "%1$s 和他悲哀的护甲一同被击穿了");
        language.add("death.attack.summon_damage_type", "%1$s was flogged mercilessly", "%1$s 被抽得皮开肉绽");
        language.add("death.attack.summoner_damage_type", "%1$s failed to communicate in time", "%1$s 没能及时沟通");
        language.add("description.confluence.secret_seeds_selection.boulder_world", "You know what? The world is actually one giant boulder. So everything in the world is a boulder.", "你知道吗？世界其实是一个巨大的巨石。所以世界上的万物都是巨石。");
        language.add("description.confluence.secret_seeds_selection.celebrationmk10", "10 years of Terraria! Join the party in this colorful world of whimsy - who knows, maybe the team left some gifts behind for you to open.", "泰拉瑞亚十周年!在这个多姿多彩的奇幻世界中一起庆祝——谁知道呢，也许团队留下了一些礼物等你拆开。");
        language.add("description.confluence.secret_seeds_selection.dont_dig_up", "A land where up is down and down is up. Turn Minecraft on its head in this inverted adventure. Will you be brave enough to explore The Up?", "生于下界，而后探索上下翻转的世界！在这场乾坤倒转的冒险中，你是否能重见天日？");
        language.add("description.confluence.secret_seeds_selection.drunk_world", "Crimson & Corruption? Together? Madness. This is the land of world generation gone wild, leading to a Terraria adventure like no other! Go home worldgen, you are drunk!", "猩红加上腐化？两者一同出现？唯有疯狂！这次融合，世界陷入疯狂境地，带来一次绝无仅有的冒险！沉沦吧，世界，你喝醉了！");
        language.add("description.confluence.secret_seeds_selection.empty", "Please choose how your world will be built with the options above.", "请选择上述选项来构建你的世界。");
        language.add("description.confluence.secret_seeds_selection.for_the_worthy", "Are you Worthy? This is a world of no mercy Forget what you know and sharpen your skills, lest you be weighed, measured, and found wanting...", "你是勇者吗？这是一个毫无怜悯的世界。忘记所知的一切并磨练技能，免得你被考察、衡量，并被发现不合格……");
        language.add("description.confluence.secret_seeds_selection.get_fixed_boi", "For the Worthy wasn't enough? Featuring aspects of every other world seed combined with some brand new surprises, this world is here to break you. Get Fixed, boi!", "这个世界就像天顶剑一样！混合了所有其他种子的主要特色！再加上一些意外因素，它就是为了击败你而生。准备受死吧，伙计！");
        language.add("description.confluence.secret_seeds_selection.never_sleep", "Sleeping is a waste of time! We shall never sleep! (Beds cannot be used)", "睡觉太浪费时间了！我们应该永远不睡觉！（无法使用床）");
        language.add("description.confluence.secret_seeds_selection.no_traps", "Whoa, Traps. Ya hate 'em, right? I hate them myself! This world has definitely been stripped of any and all traps... we think. Maybe.", "哇，陷阱，你讨厌它们，我也讨厌它们！这个世界毫无疑问去除掉了所有的陷阱...应该是这样的，也许吧。");
        language.add("description.confluence.secret_seeds_selection.normal", "Welcome to Confluence! Embark on your adventures with the original Terraria experience and gameplay.", "交流汇合的来世，这次你的旅途与两个世界的命运重合与一体。开始冒险，在融合世界中探索吧！");
        language.add("description.confluence.secret_seeds_selection.not_the_bees", "Enter a land oozing with syrupy honey, where the buzzing of wings and thr threat of venomous singers awaits around every turn! (Wicker helmet not included)", "进入一片弥漫着甜腻蜂香的大陆，在这里嗡嗡振翅声和有毒蛰刺的威胁潜伏在每一个角落！（不包括柳条头盔）");
        language.add("description.confluence.secret_seeds_selection.really_small", "I get all the reasons, but why is this bird so big?", "道理我都懂，可是这只鸟为什么这么大？");
        language.add("description.confluence.secret_seeds_selection.secret_seed", "More secret worlds, parallel timelines, and chaotic journeys await your exploration.", "更多秘密的世界，平行的时空，错乱的旅途等待着你的探索。");
        language.add("description.confluence.secret_seeds_selection.skyblock", "Enter a realm floating in the sky. With little to start with, you must build up your world from humble beginnings.", "踏入这片悬浮于天际的领域。初始资源微薄，你需白手起家，逐步构建属于你的世界。");
        language.add("description.confluence.secret_seeds_selection.the_constant", "Bringing the Don't Starve Together adventure into Terraria, can you survive persistent hunger as you seek to save Minecraft? Oh, and don't forget to stay in the light!", "将《饥荒》冒险融入到泰拉瑞亚与我的世界之中，你能否在战胜持续饥饿的同时找到世界的拯救之道?哦，还有别忘了待在光明处!");
        language.add("description.confluence.secret_seeds_selection.too_easy", "So, you have elected the way of pain... (World starts in Hardmode)", "敬酒不吃吃罚酒...（世界开局就是困难模式）");
